users = list_users({})
days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
// For each day, get availability for all users in parallel
day_busy = for day in days {
  user_avails = for u in users {
    avail = boundary retry 2 {
      return get_availability({ user_id: u.id, date: day })
    } catch err {
      return fail("AVAIL", err.message)
    }
    return avail.busy if avail.busy != null else []
  }
  return { day: day, busies: user_avails }
}
return { users: users, day_busy: day_busy }

// Possible starts: 09:00 to 16:00 in 30-min steps
starts_hhmm = ["09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00"]

to_min = fun(t) {
  parts = text.split(t, ":")
  return number.parse(parts[0]) * 60 + number.parse(parts[1])
}

// Check if [slot_start, slot_end) overlaps [busy_start, busy_end)
overlaps = fun(ss, se, bs, be) {
  return ss < be and bs < se
}

day_busy = [
  {day: "2026-06-15", busies: [[{"end":"12:00","start":"09:00"}],[{"end":"15:00","start":"11:30"}],[{"end":"17:00","start":"14:30"}],[{"end":"11:00","start":"10:00"}]]},
  {day: "2026-06-16", busies: [[{"end":"17:00","start":"13:00"}],[{"end":"13:30","start":"09:00"}],[],[{"end":"12:00","start":"11:00"}]]},
  {day: "2026-06-17", busies: [[{"end":"11:00","start":"09:00"}],[{"end":"14:00","start":"10:30"}],[{"end":"10:00","start":"09:00"}],[{"end":"16:30","start":"15:30"}]]},
  {day: "2026-06-18", busies: [[{"end":"09:30","start":"09:00"}],[],[],[]]},
  {day: "2026-06-19", busies: [[],[],[{"end":"17:00","start":"16:00"}],[]]}
]

// Find earliest free slot
found = fold acc = null for day_info in day_busy {
  skip if acc != null
  // Try each start time
  day_result = fold dacc = null for st in starts_hhmm {
    skip if dacc != null
    sm = to_min(st)
    em = sm + 60
    // end as hh:mm
    eh = number.floor(em / 60)
    emin = em - eh * 60
    et = (text.slice("0" + json.encode(eh), -2)) + ":" + (text.slice("0" + json.encode(emin), -2))

    // Check all users free
    any_busy = fold busy_flag = false for user_busy in day_info.busies {
      skip if busy_flag
      user_conflict = fold c = false for b in user_busy {
        skip if c
        bs = to_min(b.start)
        be = to_min(b.end)
        return true if overlaps(sm, em, bs, be) else false
      }
      return true if user_conflict else false
    }
    return { start: day_info.day + "T" + st + ":00Z", end: day_info.day + "T" + et + ":00Z" } if not any_busy else null
  }
  return day_result
}

return found

